ruleSearch.intro:
&emsp;&emsp;{{$.target.abstract}}
<js>
let type_name = java.getString("$.type_name");
let tishi = "---复制下面文字添加至发现规则--";

if(type_name=="用户" || type_name=="日记"){
	result = result + `\n&lrm;\n${tishi}\n&lrm;\n${java.getString("$.target.name||$.target.owner.name")}的日记::${java.getString("$.target.url||$.target.owner.url")}notes?start={{(page-1)*10}\}&type=note`

	}else if(type_name=="讨论"){
		result = result + `\n&lrm;\n🔰所属小组:${java.getString("$.target.owner.name")}\n${tishi}\n&lrm;\n${java.getString("$.target.owner.name")}::https://www.douban.com/group/${java.getString("$.target.owner.id")}/discussion?start={{(page-1)*25}\}`

		}
</js>

ruleToc.nextTocUrl:
@js:
if(!/data:|start=10/.test(baseUrl)){
let page = Number(/span class="next">/.test(result)?result.match(/>(\d+)<\/a>\s+<span class="next">/)[1]:0);
page = page>10?10:page;
list = [];
for(i=2;i<=2;i++){
	list.push(baseUrl+"?start="+(i-1)*10+"&type=note")
	}
list
}

ruleContent.content:
$.content
<js>
saybody = java.getString("$.sayBody");
chapterintro = java.get("chapterintro");
pointMeassge = java.get("pointmeassge");
message = java.getString("$.message");
content = "\n"+chapterintro+"\n"+message+"\n"+"价格："+pointMeassge+"（APP专享价）";
saybody = saybody!=""?"\n"+"▍作者有话说："+saybody:"";
Content = result==""?content:result+saybody
</js>

ruleToc.chapterName:
$.chaptername##第(\d+|\s\d+\s)章\s*|[第]?[零一二三四五六七八九十百千万两]+章\s*|(?=^)\d+(?=$)
<js>
pointMeassge = java.getString("$.pointMeassge");
java.put("pointmeassge",pointMeassge);
chapterid = java.getString("$.chapterid");
chaptertype = java.getString("$.chaptertype");
islockMessage = java.getString("$.islockMessage") =='[本章节已锁定]'?'[本章节已锁定]':'';
isvip = java.getString("$.isvip") == '0'?'':'💰';
ChapterName = chaptertype=="0"?isvip+'第'+chapterid+'章 '+result+islockMessage:result
</js>

ruleToc.updateTime:
$.chapterintro##(?![A-Za-z0-9]+)\s*(?![A-Za-z0-9]+)
<js>
java.put("chapterintro",result);
chapterintro = result;
chapterdate = java.getString("$.chapterdate");
chaptersize = java.getString("$.chaptersize");
chaptertype = java.getString("$.chaptertype");
ChapterInfo = chaptertype=="0"?chapterdate+'　'+chaptersize+'字'+'　'+chapterintro:""
</js>

